    if (err instanceof SyntaxError) throw new InputError(`Error: ${name}: invalid JSON`, 3);
    throw new InputError(`Error: ${name}: too deep`, 3);
  }
  if (textDepth(text) > MAX_DEPTH) throw new InputError(`Error: ${name}: too deep`, 3);
  return value;
}

